// ServerServiceHandler is an implementation of the zonhoren.phron.v1.ServerService service.
type ServerServiceHandler interface {
	// GetServerPricing returns the Server Price in effect and the size rules
	// that go with it. When no Server Price has been set yet, price and
	// rules are absent and no Server can be created.
	GetServerPricing(context.Context, *connect.Request[v1.GetServerPricingRequest]) (*connect.Response[v1.GetServerPricingResponse], error)
	// QuoteServer checks a size against the size rules in effect and prices it.
	// A size that breaks a rule comes back with its problems and no price; this
	// is an answer, not an error. The create form calls it as the customer
	// edits the size.
	QuoteServer(context.Context, *connect.Request[v1.QuoteServerRequest]) (*connect.Response[v1.QuoteServerResponse], error)
	// ListOperatingSystems lists the Operating Systems a new Server can be
	// created from.
	ListOperatingSystems(context.Context, *connect.Request[v1.ListOperatingSystemsRequest]) (*connect.Response[v1.ListOperatingSystemsResponse], error)
	// ListServerLocations lists every Location a Server can live in, each with
	// whether new Servers can be created there now. A Location is offered while
	// it has capacity that takes new Servers, read live; one that is
	// not says why in available/unavailable_reason.
	ListServerLocations(context.Context, *connect.Request[v1.ListServerLocationsRequest]) (*connect.Response[v1.ListServerLocationsResponse], error)
	// CreateServer creates a Server and starts its build. Billing starts when it
	// is accepted. FAILED_PRECONDITION when the balance is not positive or the
	// Organization has not passed its identity check (a pass never runs out);
	// RESOURCE_EXHAUSTED when
	// the platform has no room for another Server of that size in the chosen
	// Location (the message says so and nothing is charged); INVALID_ARGUMENT
	// for a Location that is unknown or not offered now; NOT_FOUND for an
	// unknown or no longer offered Operating System or SSH key. There is no limit on the
	// number of Servers an Organization may have beyond its balance and the
	// platform's capacity.
	//
	// Idempotent on request_id: repeating a call with the same request_id and
	// the same fields returns the same Server and creates no second one. The
	// same request_id with different fields is ALREADY_EXISTS.
	CreateServer(context.Context, *connect.Request[v1.CreateServerRequest]) (*connect.Response[v1.CreateServerResponse], error)
	// ListServers lists the Organization's Servers, newest first.
	ListServers(context.Context, *connect.Request[v1.ListServersRequest]) (*connect.Response[v1.ListServersResponse], error)
	GetServer(context.Context, *connect.Request[v1.GetServerRequest]) (*connect.Response[v1.GetServerResponse], error)
	// DeleteServer deletes a Server, its disk and its backups, and releases its
	// /64, for good. Billing stops when the Server is gone. Works at any balance
	// and in any state but DELETED, unless the Server is quarantined;
	// idempotent. The response carries the Server in state DELETING.
	DeleteServer(context.Context, *connect.Request[v1.DeleteServerRequest]) (*connect.Response[v1.DeleteServerResponse], error)
	// StartServer powers a stopped Server on. Idempotent for a Server that is
	// running; FAILED_PRECONDITION while it is being created or deleted, or
	// while it is quarantined.
	StartServer(context.Context, *connect.Request[v1.StartServerRequest]) (*connect.Response[v1.StartServerResponse], error)
	// StopServer powers a Server off: gracefully by default, asking the guest to
	// shut down, or at once when force is set (the same as pulling the power). A
	// stopped Server is still billed. Idempotent for a Server that is already
	// stopped; FAILED_PRECONDITION while it is being created or deleted.
	StopServer(context.Context, *connect.Request[v1.StopServerRequest]) (*connect.Response[v1.StopServerResponse], error)
	// RebootServer asks the guest to restart. FAILED_PRECONDITION unless the
	// Server is running.
	RebootServer(context.Context, *connect.Request[v1.RebootServerRequest]) (*connect.Response[v1.RebootServerResponse], error)
	// ResizeServer changes a Server's vCPUs, memory and disk. The new size keeps
	// the size rules in effect (INVALID_ARGUMENT naming the problems, as
	// QuoteServer does), keeps the Server's tier (a change of tier is
	// INVALID_ARGUMENT: Shared and Dedicated Servers run on different hosts) and
	// never shrinks the disk (INVALID_ARGUMENT). A size that needs capacity no
	// host has free is RESOURCE_EXHAUSTED with a customer sentence. What happens
	// to the running Server:
	// - fewer vCPUs or less memory, or Dedicated: it restarts with the new size;
	// - more vCPUs or memory, Shared: it moves to another host while it runs, or
	//   restarts with the new size when none has room or prefer_restart is set;
	//   either way it keeps its address;
	// - more disk only: grown in place with no restart.
	// A stopped Server stays stopped and starts with the new size. An hour is
	// billed at the most expensive size allocated during it: a larger size from
	// the hour of the resize, a smaller one from the hour after the Server has
	// it. Only a RUNNING or STOPPED Server can be resized (FAILED_PRECONDITION
	// otherwise, and while quarantined). Returns once accepted; the Server's
	// `size` reads the new size from then on.
	ResizeServer(context.Context, *connect.Request[v1.ResizeServerRequest]) (*connect.Response[v1.ResizeServerResponse], error)
	// ListSshKeys lists the Organization's saved SSH keys.
	ListSshKeys(context.Context, *connect.Request[v1.ListSshKeysRequest]) (*connect.Response[v1.ListSshKeysResponse], error)
	// CreateSshKey saves a public key. INVALID_ARGUMENT for a key that is not a
	// valid OpenSSH public key; ALREADY_EXISTS when the Organization already has
	// a key with that fingerprint.
	CreateSshKey(context.Context, *connect.Request[v1.CreateSshKeyRequest]) (*connect.Response[v1.CreateSshKeyResponse], error)
	// DeleteSshKey removes a saved key. Servers already created with it keep it.
	// Idempotent.
	DeleteSshKey(context.Context, *connect.Request[v1.DeleteSshKeyRequest]) (*connect.Response[v1.DeleteSshKeyResponse], error)
	// GetServerFirewall returns a Server's customer firewall with its revision.
	GetServerFirewall(context.Context, *connect.Request[v1.GetServerFirewallRequest]) (*connect.Response[v1.GetServerFirewallResponse], error)
	// ReplaceServerFirewall replaces the whole customer firewall: every rule in
	// order, and both defaults. FAILED_PRECONDITION when revision is not the
	// current one (someone changed the firewall since it was read): read it
	// again and retry. INVALID_ARGUMENT for a rule that breaks the rules in
	// ServerFirewallRule, or a list longer than the platform allows. Takes
	// effect on the running Server without a restart.
	ReplaceServerFirewall(context.Context, *connect.Request[v1.ReplaceServerFirewallRequest]) (*connect.Response[v1.ReplaceServerFirewallResponse], error)
	// RequestServerMailPorts asks for outbound mail ports 25 and 465 to be
	// opened for a Server. Phron answers after a waiting period; until then the
	// Server's mail_ports reads REQUESTED. Idempotent while a request is
	// pending; FAILED_PRECONDITION when the ports are already open or the Server
	// is FAILED, DELETING or DELETED.
	RequestServerMailPorts(context.Context, *connect.Request[v1.RequestServerMailPortsRequest]) (*connect.Response[v1.RequestServerMailPortsResponse], error)
	// ListServerBackups lists a Server's saved copies, both kinds: the daily
	// Backups and the on-demand Snapshots, told apart by ServerBackup.kind.
	// Newest first. Only copies that have not expired. server_id may name a
	// DELETED Server of the Organization (ListServers with include_deleted
	// finds it): its Backups and Snapshots stay listed for seven days after its
	// deletion and can start a new Server (CreateServerRequest.restore_from_backup_id).
	ListServerBackups(context.Context, *connect.Request[v1.ListServerBackupsRequest]) (*connect.Response[v1.ListServerBackupsResponse], error)
	// CreateServerSnapshot takes an on-demand Snapshot of a running or stopped
	// Server's disk. The response carries it in state CREATING.
	// FAILED_PRECONDITION when the Server already has three Snapshots (delete
	// one first), or is not running or stopped.
	CreateServerSnapshot(context.Context, *connect.Request[v1.CreateServerSnapshotRequest]) (*connect.Response[v1.CreateServerSnapshotResponse], error)
	// DeleteServerSnapshot deletes a Snapshot. FAILED_PRECONDITION for a Backup:
	// those expire by themselves. Idempotent.
	DeleteServerSnapshot(context.Context, *connect.Request[v1.DeleteServerSnapshotRequest]) (*connect.Response[v1.DeleteServerSnapshotResponse], error)
	// RestoreServer replaces a live Server's disk with the contents of one of its
	// own Backups or Snapshots. The Server keeps its /64 and its size,
	// and the backup itself is kept. The call returns once the restore has
	// started. First a copy of the disk as it is now is taken and waited for (a
	// ServerBackup of kind PRE_RESTORE: outside the Snapshot cap, kept seven days;
	// minutes, by disk size), so a restore can be undone; the Server runs while
	// that is taken. If the copy cannot be taken the restore does not go on and
	// the Server is left as it was. Then the Server is stopped while its disk is
	// replaced and started again afterwards if it was running. The Server reads
	// PROVISIONING for the whole of it. The disk is replaced, not kept: a
	// restore that fails leaves the Server stopped with no usable disk, and the
	// customer asks again (the copy is kept). A deleted Server is not restored
	// in place: its copies start a new Server
	// (CreateServerRequest.restore_from_backup_id).
	// FAILED_PRECONDITION unless the backup is READY and the Server is running
	// or stopped.
	RestoreServer(context.Context, *connect.Request[v1.RestoreServerRequest]) (*connect.Response[v1.RestoreServerResponse], error)
	// GetServerTraffic returns a Server's network traffic in hourly buckets
	// over a time range. An hour with no measurement has no bucket, which is not
	// the same as zero traffic.
	GetServerTraffic(context.Context, *connect.Request[v1.GetServerTrafficRequest]) (*connect.Response[v1.GetServerTrafficResponse], error)
}

